_CINEMATIC_LIVE_ACTION_STYLE_RE = re.compile(
    r"(?:^|[.;|]\s*)(?:(?:Global\s+style|Style)\s*:\s*)?[^.;|]{0,500}"
    r"\b(?:cinematic\s+live[- ]action\s+historical\s+drama|"
    r"photorealistic\s+(?:cinematic\s+)?(?:live[- ]action|feature[- ]film))\b",
    re.IGNORECASE,
)
_LIVE_ACTION_CONFLICTING_NEGATIVE_RE = re.compile(
    r"\b(?:photorealistic(?:\s+photo)?|photorealism|photographic(?:\s+still)?|"
    r"live[- ]action(?:\s+still)?|raw(?:\s+camera)?\s+photo)\b",
    re.IGNORECASE,
)


def _uses_cinematic_live_action_style(prompt: str) -> bool:
    return bool(_CINEMATIC_LIVE_ACTION_STYLE_RE.search(str(prompt or "")))


def _live_action_safe_negative_terms(values: Iterable[str]) -> list[str]:
    return [
        value
        for value in values
        if value and not _LIVE_ACTION_CONFLICTING_NEGATIVE_RE.search(value)
    ]


def supports_scene_contract_v2_model(model_id: object) -> bool:
    model = str(model_id or "").strip().lower()
    return (
        model in {"comfyui-krea2", "comfyui-krea2-expression"}
        or
        model.startswith("comfyui-flux2-")
        or model.startswith("comfyui-dreamshaper-xl")
        or model.startswith("comfyui-z-image-")
    )

