def _apply_baekje_ep01_later_record_context(
    spec: _SceneSpec,
    fields: dict[str, str],
) -> None:
    if _field(fields, "Culture scope") != _BAEKJE_EP01_FOUNDATION_CULTURE:
        return
    narration = _field(fields, "Narration context")
    if narration in _BAEKJE_EP01_LATER_RECORD_NARRATIONS:
        spec.era = "Later historical compilation; exact date unspecified"
        spec.place = "a plain later archival setting"
        spec.material = (
            "closed blank unmarked manuscript covers, plain unlabeled wooden archival "
            "surfaces and only the explicitly requested plain markers"
        )
        if narration in {
            "다만 건국 기사는 사건보다 훨씬 뒤에 정리된 전승이어서, 생중계 기록은 아니죠",
            "한 계보에서는 부여계 인물 우태가 두 형제의 아버지였고",
        }:
            spec.material = (
                "traditional East Asian thread-bound manuscript with a flexible aged tan cover, "
                "visible external binding thread and stacked folded leaves; plain unlabeled wooden "
                "archival surface; only explicitly requested flat rectangular identification tags"
            )
    elif narration in _BAEKJE_EP01_LATER_COMPARATIVE_NARRATIONS:
        spec.era = "Later comparative historical records; exact compilation date unspecified"
        spec.place = "a plain later archival setting"

    if narration in _BAEKJE_EP01_NONHUMAN_MATERIAL_FREE_NARRATIONS:
        spec.material = ""
    elif narration == "마한은 백제보다 먼저 한강 이남에 자리한 여러 소국의 연맹이었습니다":
        spec.material = (
            "plain timber palisades, packed-earth paths and rough thatch roofs at separated small settlements"
        )


