def _apply_baekje_ep01_exact_scene_narration_lock(
    spec: _SceneSpec,
    fields: dict[str, str],
) -> tuple[tuple[str, ...], bool, bool]:
    if _field(fields, "Culture scope") != _BAEKJE_EP01_FOUNDATION_CULTURE:
        return (), False, False
    scene = _field(fields, "Scene")
    narration = _field(fields, "Narration context")
    for (exact_sentence, exact_narration), lock in _BAEKJE_EP01_LATE_EXACT_LOCKS.items():
        if not scene.startswith(exact_sentence) or narration != exact_narration:
            continue
        subject, action, negative_terms, allows_secondary_people = lock
        spec.subject = subject
        spec.action = action
        spec.evidence = ""
        return negative_terms, allows_secondary_people, True
    return (), False, False


