def _apply_ch3_ep11_amanoiwato_scene_lock(
    spec: _SceneSpec,
    fields: dict[str, str],
) -> tuple[tuple[str, ...], bool]:
    if _field(fields, "Culture scope") != "Kojiki and Nihon Shoki Japanese creation myth":
        return (), False
    narration = _field(fields, "Narration context")
    lock = CH3_EP11_AMANOIWATO_NARRATION_SCENE_LOCKS.get(narration)
    if lock is None:
        lock = CH3_EP11_AMANOIWATO_NARRATION_SCENE_LOCKS.get(
            narration.rstrip(".!?。！？")
        )
    if lock is None:
        return (), False
    subject, action, material = lock
    spec.subject = subject
    spec.action = action
    spec.material = material
    spec.evidence = ""
    extra = CH3_EP11_AMANOIWATO_EXTRA_NEGATIVES.get(narration, ())
    return tuple(dict.fromkeys((*extra, *CH3_EP11_AMANOIWATO_COMMON_NEGATIVES))), True


