def _apply_baekje_ep01_foundation_scene_lock(
    spec: _SceneSpec,
    fields: dict[str, str],
) -> tuple[tuple[str, ...], bool]:
    expected_period = (
        f"{_BAEKJE_EP01_FOUNDATION_YEAR}; "
        f"{_BAEKJE_EP01_FOUNDATION_CULTURE} historical context"
    )
    if _field(fields, "Year/period") != expected_period:
        return (), False
    if _field(fields, "Culture scope") != _BAEKJE_EP01_FOUNDATION_CULTURE:
        return (), False

    scene = _field(fields, "Scene")
    spec.material = _BAEKJE_EP01_FOUNDATION_MATERIAL
    narration = _field(fields, "Narration context")
    narration_lock = _BAEKJE_EP01_FOUNDATION_EXACT_NARRATION_LOCKS.get(narration)
    if narration_lock is not None:
        subject, action, extra_negatives, allows_secondary_people = narration_lock
        spec.subject = subject
        spec.action = action
        spec.material = _BAEKJE_EP01_EXACT_MATERIAL_OVERRIDES.get(
            narration,
            _BAEKJE_EP01_FOUNDATION_MATERIAL,
        )
        spec.evidence = ""
        return (
            (*_BAEKJE_EP01_FOUNDATION_NEGATIVES, *extra_negatives),
            allows_secondary_people,
        )
    for (exact_sentence, exact_narration), lock in (
        _BAEKJE_EP01_FOUNDATION_NARRATION_LOCKS.items()
    ):
        if not scene.startswith(exact_sentence) or narration != exact_narration:
            continue
        subject, action, extra_negatives, allows_secondary_people = lock
        spec.subject = subject
        spec.action = action
        spec.material = _BAEKJE_EP01_FOUNDATION_MATERIAL
        spec.evidence = ""
        return (
            (*_BAEKJE_EP01_FOUNDATION_NEGATIVES, *extra_negatives),
            allows_secondary_people,
        )
    for exact_sentence, lock in _BAEKJE_EP01_FOUNDATION_SCENE_LOCKS.items():
        if not scene.startswith(exact_sentence):
            continue
        subject, action, extra_negatives, allows_secondary_people = lock
        spec.subject = subject
        spec.action = action
        spec.evidence = ""
        return (
            (*_BAEKJE_EP01_FOUNDATION_NEGATIVES, *extra_negatives),
            allows_secondary_people,
        )
    return _BAEKJE_EP01_FOUNDATION_NEGATIVES, False


