def _apply_baekje_ep07_domi_scene_lock(
    spec: _SceneSpec,
    fields: dict[str, str],
) -> tuple[tuple[str, ...], int | None, str | None, bool]:
    if not re.search(
        r"\bSource\s+workbook\s+row\s+07-\d{3}\b",
        spec.source,
        re.IGNORECASE,
    ):
        return (), None, None, False
    if not re.search(r"\bBaekje\b", spec.source, re.IGNORECASE):
        return (), None, None, False

    narration = _field(fields, "Narration context").rstrip(".!?。！？,，")
    lock = _BAEKJE_EP07_DOMI_SCENE_LOCKS.get(narration)
    if lock is None:
        return (), None, None, False

    subject, action, material, person_count, scene_kind = lock
    spec.subject = subject
    spec.action = action
    spec.material = material
    spec.evidence = ""
    spec.era = (
        "early Hanseong Baekje legend traditionally assigned to King Gaeru; exact year uncertain"
    )
    spec.place = "Han River basin, early Hanseong Baekje"
    spec.culture = "early Baekje"
    resolved_scene_kind = (
        "scene"
        if scene_kind == "landscape"
        and person_count is not None
        and person_count > 0
        else scene_kind
    )
    extra_negatives = (
        _BAEKJE_EP07_WILD_RIVER_NEGATIVES
        if material == _BAEKJE_EP07_WILD_RIVER_MATERIAL
        else ()
    )
    if narration in {
        "이야기는 그녀가 끝내 강어귀에 이르렀다고만 전합니다",
        "앞에는 건너야 할 물이 있었고 뒤에는 돌아갈 수 없는 왕궁이 있었죠",
        "왕의 명령보다 자신의 판단을 앞세운 주체적인 행동으로 읽힙니다",
    }:
        extra_negatives = (
            *extra_negatives,
            "boat",
            "watercraft",
            "vessel",
            "oar",
            "raft",
        )
    if narration == "도미 부인의 이야기는 왕의 명령이 곧 정의가 될 수 없다고 말합니다":
        extra_negatives = (
            *extra_negatives,
            "armor",
            "helmet",
            "headwear",
            "weapon",
            "sword",
            "spear",
            "baton",
        )
    if material == _BAEKJE_EP07_LATE_HANSEONG_MATERIAL:
        extra_negatives = (
            *extra_negatives,
            "tower",
            "gate tower",
            "fortress tower",
            "palace roof",
            "ceramic roof",
            "roof tile",
            "tile roof",
            "pagoda",
            "ornate eaves",
            "multi-story building",
            "Chinese fortress",
            "Japanese castle",
        )
    return (
        (*_BAEKJE_EP07_DOMI_COMMON_NEGATIVES, *extra_negatives),
        person_count,
        resolved_scene_kind,
        True,
    )


