def _apply_ch2_registered_scene_lock(
    spec: _SceneSpec,
    model_id: str,
) -> tuple[tuple[str, ...], int | None, str | None, bool]:
    scene_excerpt = _classification_scene_excerpt(spec.action).lower()
    scene_locks = dict(_CH2_REGISTERED_SCENE_LOCKS)
    if str(model_id or "").lower().startswith("comfyui-flux2-"):
        scene_locks.update(_CH2_REGISTERED_FLUX_SCENE_OVERRIDES)
    for key, (subject, action, negatives, person_count, scene_kind) in scene_locks.items():
        if key in scene_excerpt:
            spec.subject = subject
            spec.action = action
            if (
                str(model_id or "").lower().startswith("comfyui-flux2-")
                and key
                == "sleeping ymir generating a male and female beneath his arms and another being from his legs"
            ):
                spec.evidence = (
                    "One large horizontal Ymir petroglyph above exactly three separate single "
                    "petroglyphs in left, center, and right lower slots"
                )
            elif (
                str(model_id or "").lower().startswith("comfyui-flux2-")
                and key == "split tableau of manu's sacrifice and ngwhi stealing trito's cattle"
            ):
                spec.evidence = (
                    "One continuous steppe view with Manu and motionless Yemo in the foreground "
                    "and one separate serpent driving cattle in the far background"
                )
