def _apply_ch2_europa_episode_continuity_lock(
    spec: _SceneSpec,
) -> tuple[tuple[str, ...], int | None, str | None, bool]:
    scene_excerpt = _classification_scene_excerpt(spec.action).lower()
    for key, (subject, action, negatives, person_count, scene_kind) in (
        _CH2_EUROPA_EPISODE_CONTINUITY_LOCKS.items()
    ):
        if key in scene_excerpt:
            spec.subject = subject
            spec.action = action
            if key in _CH2_EUROPA_SUPPRESS_SOURCE_EVIDENCE_KEYS:
                spec.evidence = ""
            if key == "excavators comparing knossos ruins":
                spec.era = "modern archaeological investigation of Bronze Age remains"
                spec.place = "Knossos excavation trench in Crete"
                spec.culture = "modern archaeology examining Minoan and Pylos evidence"
                spec.material = (
                    "plain modern field clothing, soft excavation brushes, undecorated "
                    "archival trays, Bronze Age masonry, ceramic fragments"
                )
            elif key == "anaximander and hecataeus drawing tripartite world maps with europe":
                spec.era = "6th century BCE"
                spec.place = "Ionian Greek workshop at Miletus"
                spec.culture = "Archaic Ionian Greek geographic inquiry"
                spec.material = (
                    "plain wool tunics, one wooden table, one damp circular clay slab, "
                    "two simple wooden styluses"
                )
            elif key == "herodotus comparing different river boundaries between europe and asia":
                spec.era = "5th century BCE"
                spec.place = "natural river frontier north of the Black Sea"
                spec.culture = "Classical Greek geographic inquiry"
                spec.material = "plain wool travel clothing, natural river stones, reeds, water"
            elif key == "european eastern boundary shifting across successive ancient and modern maps":
                spec.era = "comparative historical geography"
                spec.place = (
                    "eastern Europe from the Caucasus foothills across the Don steppe "
                    "to the Ural Mountains"
                )
                spec.culture = ""
                spec.material = "natural river channels, open steppe, forested foothills, mountains"
            return negatives, person_count, scene_kind, True
    return (), None, None, False


def _proper_human_name_keys(text: str) -> set[str]:
    excerpt = _classification_scene_excerpt(text)
    names: set[str] = set()
    for match in _PROPER_HUMAN_CANDIDATE_RE.finditer(excerpt):
        words = match.group(0).split()
        possessive = bool(words and re.search(r"['’]s$", words[-1], re.IGNORECASE))
        if possessive:
            words[-1] = re.sub(r"['’]s$", "", words[-1], flags=re.IGNORECASE)
        while words and words[0].lower() in _PROPER_HUMAN_LEADING_MODIFIERS:
            words.pop(0)
        if not words:
            continue
        key = " ".join(words).lower()
        if key in _PROPER_HUMAN_NON_PERSON_NAMES or key in _PROPER_HUMAN_NONHUMAN_NAMES:
            continue
        if all(word.lower() in _PROPER_HUMAN_NON_PERSON_NAMES for word in words):
            continue
        suffix = ("'s " if possessive else "") + excerpt[match.end() : match.end() + 60]
        if _INVISIBLE_POSSESSIVE_OBJECT_RE.match(suffix):
            continue
        prefix = excerpt[max(0, match.start() - 40) : match.start()]
        if re.search(r"\bonce\s+associated\s+with\s*$", prefix, re.IGNORECASE):
            continue
        names.add(key)
    return names


def _counted_human_groups(text: str) -> tuple[int, tuple[tuple[int, int], ...]]:
    total = 0
    spans: list[tuple[int, int]] = []
    for match in _COUNTED_HUMAN_GROUP_RE.finditer(text):
        token = match.group(1).lower()
        value = _COUNT_WORDS.get(token, int(token) if token.isdigit() else 0)
        if value:
            total += value
            spans.append(match.span())
    for match in _EXACT_PAIR_PHRASE_RE.finditer(text):
        total += 2
        spans.append(match.span())
    return total, tuple(spans)


def _has_indeterminate_human_group(
    text: str,
    counted_spans: tuple[tuple[int, int], ...] = (),
) -> bool:
    for match in _INDETERMINATE_HUMAN_GROUP_RE.finditer(text):
        if any(start <= match.start() and match.end() <= end for start, end in counted_spans):
            continue
        return True
    return False


def _anonymous_human_role_count(text: str, *, named_count: int) -> int:
    excerpt = _classification_scene_excerpt(text)
    count = 0
    if re.search(r"\ba\s+male\s+and\s+female\b", excerpt, re.IGNORECASE):
        count += 2
    if re.search(r"\banother\s+(?:human|person|male|female|being|figure)\b", excerpt, re.IGNORECASE):
        count += 1
    role_list = re.search(
        r"\b(?:toward|around|links?|linked\s+around)\s+(?:a\s+)?"
        r"((?:god|priest|warrior|herder|chieftain|ruler|king|queen|protector)"
        r"(?:\s*,\s*(?:god|priest|warrior|herder|chieftain|ruler|king|queen|protector))*"
        r"\s*,?\s+and\s+(?:god|priest|warrior|herder|chieftain|ruler|king|queen|protector))\b",
        excerpt,
        re.IGNORECASE,
    )
    if role_list:
        count += len(
            re.findall(
                r"\b(?:god|priest|warrior|herder|chieftain|ruler|king|queen|protector)\b",
                role_list.group(1),
                re.IGNORECASE,
            )
        )
    elif re.search(r"\b(?:beside|with|toward|before|near)\s+(?:a|an|the)\s+(?:[a-z-]+\s+){0,3}(?:deity|god|priest|warrior|herder|chieftain|ruler|king|queen|helper)\b", excerpt, re.IGNORECASE):
        count += 1
    if re.search(r"\band\s+the\s+(?:[a-z-]+\s+){0,3}(?:helper|deity|god|priest|warrior|herder|chieftain|ruler|king|queen)\b", excerpt, re.IGNORECASE):
        count += 1
    if named_count and re.search(
        r"\b(?:over|dismembers?|beside|before)\s+(?:the\s+)?(?:fallen|defeated|dismembered)\s+"
        r"(?:man|woman|king|queen|ruler|warrior|person|figure)\b",
        excerpt,
        re.IGNORECASE,
    ):
        count += 1
    if named_count and re.search(r"\band\s+(?:his|her|their)\s+(?:wife|husband|spouse)\b", excerpt, re.IGNORECASE):
        count += 1
    if named_count == 0:
        leading_roles = re.match(
            r"^(?:Early\s+)?"
            r"((?:God|Priest|Warrior|Herder|Chieftain|Ruler|King|Queen|Protector)"
            r"(?:\s*,\s*(?:God|Priest|Warrior|Herder|Chieftain|Ruler|King|Queen|Protector))*"
            r"(?:\s*,?\s+and\s+(?:God|Priest|Warrior|Herder|Chieftain|Ruler|King|Queen|Protector))?)\b",
            excerpt,
            re.IGNORECASE,
        )
        if leading_roles:
            count += len(
                re.findall(
                    r"\b(?:god|priest|warrior|herder|chieftain|ruler|king|queen|protector)\b",
                    leading_roles.group(1),
                    re.IGNORECASE,
                )
            )
        elif re.search(r"\b(?:a\s+)?human\s+figure\b", excerpt, re.IGNORECASE):
            count += 1
    return count


def _inferred_visible_person_count(text: str) -> int | None:
    excerpt = _classification_scene_excerpt(text)
    if not excerpt or _is_symbolic_nonliteral_scene(excerpt):
        return None
    names = _proper_human_name_keys(excerpt)
    counted_total, counted_spans = _counted_human_groups(excerpt)
    if _has_indeterminate_human_group(excerpt, counted_spans):
        return None
    anonymous_total = _anonymous_human_role_count(excerpt, named_count=len(names))
    total = len(names) + counted_total + anonymous_total
    return total if 1 <= total <= 6 else None


def _explicit_person_count(text: str) -> int | None:
    subject_count = re.search(
        r"\b(?:Main|Primary)\s+subject:\s*exactly\s+"
        r"(one|two|three|four|five|six|[1-6])\s+"
        r"(?:adults?|people|persons?|males?|females?|riders?)\b",
        text,
        re.IGNORECASE,
    )
    if subject_count:
        token = subject_count.group(1).lower()
        return _COUNT_WORDS.get(token, int(token) if token.isdigit() else None)
    segment_counts: list[int] = []
    for segment in (part for part in re.split(r"\s*;\s*", text) if _clean(part)):
        matches = [
            match
            for match in _COUNT_RE.finditer(segment)
            if not _ROLE_MODIFIER_OBJECT_RE.match(segment[match.end():])
        ]
        roles = {match.group(0).lower() for match in _SINGULAR_ROLE_RE.finditer(segment)}
        if roles - {"adult", "person"}:
            roles -= {"adult", "person"}
        has_group = bool(_GROUP_RE.search(segment))
        if not matches:
            if len(roles) == 2 and not has_group:
                segment_counts.append(2)
            continue

        exact_values = [
            _COUNT_WORDS.get(
                match.group(1).lower(),
                int(match.group(1)) if match.group(1).isdigit() else 0,
            )
            for match in matches
            if match.group(0).lower().startswith("exactly ")
        ]
        if exact_values:
            segment_counts.append(max(exact_values))
            continue

        counted_roles: dict[str, int] = {}
        for match in matches:
            value = _COUNT_WORDS.get(
                match.group(1).lower(),
                int(match.group(1)) if match.group(1).isdigit() else 0,
            )
            role = match.group(2).lower()
            counted_roles[role] = max(value, counted_roles.get(role, 0))
        values = list(counted_roles.values())
        total = sum(values)
        if len(counted_roles) == 1 and has_group and values[0] == 1:
            continue
        if total == 1 and len(roles) >= 2 and not has_group:
            total = 2
        if 1 <= total <= 6:
            segment_counts.append(total)
    return max(segment_counts) if segment_counts else None


def _named_human_scene_kind(text: str) -> str | None:
    names = set(_NAMED_HUMAN_STATE_RE.findall(text))
    names.update(_NAMED_HUMAN_ACTION_RE.findall(text))
    for match in _PAIRED_NAMED_HUMAN_STATE_RE.finditer(text):
        names.update(match.groups())
    for match in _NAMED_HUMAN_LIST_ACTION_RE.finditer(text):
        names.update(re.findall(r"\b[A-Z][a-z]+\b", match.group(1)))
    for match in _NAMED_HUMAN_TWO_ACTOR_ACTION_RE.finditer(text):
        names.update(match.groups())
    if _ROLE_TO_NAMED_HUMAN_INTERACTION_RE.search(text):
        return "group"
    if len(names) >= 2:
        return "group"
    if len(names) == 1:
        return "single"
    return None


def _scene_kind(
    text: str,
    person_count: int | None,
    *,
    ch2_registered_scene: bool = False,
) -> str:
    if ch2_registered_scene and _is_symbolic_nonliteral_scene(text):
        return "scene"
    if person_count == 1:
        return "single"
    if person_count == 2:
        return "pair"
    if person_count and person_count >= 3:
        return "group"

    explicit_zero_human = bool(
        re.search(
            r"\b(?:zero[- ]person|zero\s+(?:visible\s+)?persons?|zero\s+(?:visible\s+)?people|"
            r"no\s+(?:visible\s+)?persons?|no\s+(?:visible\s+)?people|without\s+people)\b",
            text,
            re.IGNORECASE,
        )
    )
    named_human_kind = _named_human_scene_kind(text)
    human_scan = _NONVISIBLE_ROLE_OBJECT_RE.sub(" ", text) if ch2_registered_scene else text
    if ch2_registered_scene:
        _counted_total, counted_spans = _counted_human_groups(text)
        if _has_indeterminate_human_group(text, counted_spans):
            return "group"
    has_human = (
        bool(_HUMAN_RE.search(human_scan))
        or bool(_GROUP_RE.search(human_scan))
        or named_human_kind is not None
        or person_count is not None
    ) and not explicit_zero_human
    has_animal = bool(_ANIMAL_RE.search(text))
    if has_animal and person_count is None and re.search(r"\banimal[- ]only\b", text, re.IGNORECASE):
        return "animal"
    explicit_object_only = bool(re.search(r"\bobject[- ]only\b", text, re.IGNORECASE))
    object_only = explicit_zero_human or bool(_OBJECT_ONLY_RE.search(text)) or (
        bool(_OBJECT_RE.search(text)) and not has_human and not has_animal
    )
    if object_only:
        if explicit_object_only:
            return "object"
        if re.search(
            r"\bobject-only\b[^.;]{0,260}\bclosed\s+blank\s+unmarked\b[^.;]{0,260}"
            r"\b(?:coastal|night|sea-route|Daifang)\b[^.;]{0,120}\brelief\b",
            text,
            re.IGNORECASE,
        ):
            return "object"
        if re.search(
            r"\b(?:relief\s+model|terrain\s+relief|miniature|tabletop\s+model|"
            r"defense-route\s+handover\s+layout|six\s+smooth\s+grey\s+river-stone\s+fortress\s+markers|"
            r"six\s+face-down\s+bronze-capped\s+hardwood\s+fortress\s+tallies|"
            r"plain\s+bronze\s+fortress\s+alarm\s+bell|segmented\s+iron\s+helmets|"
            r"fortress\s+relief|fieldstone\s+fortress\s+wall\s+dissolving|"
            r"blood-smeared\s+five-finger\s+handprint|"
            r"discarded\s+cracked\s+Goguryeo\s+fortress\s+tally|"
            r"blank-backed\s+hardwood\s+fortress\s+tally|"
            r"(?:palm-sized\s+)?cracked\s+blank\s+hardwood\s+fortress\s+tally|"
            r"granite\s+fortress\s+wall.*center\s+melting|"
            r"gate\s+brace|locking\s+beam|timber\s+gate\s+bar)\b",
            text,
            re.IGNORECASE,
        ):
            return "object"
        if explicit_zero_human and re.search(r"\bwide\b", text, re.IGNORECASE):
            return "landscape"
        if re.search(r"\b(?:landscape|road|street|battlefield|river|mountain|field|forest|sea|storm|sky|city|village|ship|boat|fleet|wagon|carriage|ramparts?|gatehouses?|fortress(?:es)?|fortress\s+walls?|ruins?)\b", text, re.IGNORECASE):
            return "landscape"
        return "object"
    if has_animal and not has_human:
        return "animal"
    if _GROUP_RE.search(human_scan) or _BATTLE_RE.search(text) or named_human_kind == "group":
        return "group"
    if has_human:
        return "single"
    if has_animal:
        return "animal"
    return "scene"


def _anatomy_contract_text(
    contract: SceneContract,
    *,
    scene_kind: str,
    person_count: int | None,
) -> str:
    """Render only explicit scene facts plus crop-safe human topology."""
    if scene_kind not in {"single", "pair", "group"}:
        return ""
    if not (
        contract.framing
        or getattr(contract, "visible_hand_count", None) is not None
        or contract.actors
    ):
        return ""
    clauses: list[str] = []
    hand_priority_clauses: list[str] = []
    framing = (contract.framing or "").lower()
    visible_hand_count = getattr(contract, "visible_hand_count", None)

    if scene_kind in {"single", "pair", "group"}:
        if person_count:
            adult_noun = "adult" if person_count == 1 else "adults"
            clauses.append(
                f"exactly {_count_word(person_count)} separate {adult_noun}; one head and torso each"
            )
        elif scene_kind == "single":
            clauses.append("one separate adult body with one head and one torso")
        else:
            clauses.append("each visible adult has one separate head and torso")

        if framing in {"extreme facial close-up", "tight facial close-up", "head-and-shoulders"}:
            clauses.append(
                "face, neck and shoulders connected; waist and legs remain outside the crop"
            )
        elif framing == "chest-up":
            clauses.append(
                "head, neck, shoulders and chest connected; waist and legs remain outside the crop"
            )
        elif framing == "waist-up":
            clauses.append(
                "waist-up torso and arms connected; legs remain outside the crop"
            )
        elif framing == "full-body":
            clauses.append(
                "each body has one head, one torso, two arms and two legs on one ground plane"
            )
        else:
            clauses.append(
                "all visible limbs join their own body; cropped limbs end at a frame edge"
            )

        if visible_hand_count == 0:
            hand_priority_clauses.append(
                "exactly zero visible hands or fingers; wrists end outside the crop or behind stated occlusion"
            )
        elif visible_hand_count is not None:
            hand_noun = "hand" if visible_hand_count == 1 else "hands"
            hand_priority_clauses.append(
                f"exactly {_count_word(visible_hand_count)} visible {hand_noun} total"
            )
            clauses.append("each hand joins its owner's forearm")

        complete_actor_ownership = bool(
            person_count
            and len(contract.actors) == person_count
            and all(actor.visible_hand_count is not None for actor in contract.actors)
        )
        if complete_actor_ownership:
            ownership = "; ".join(
                f"{actor.slot or _clip_complete_clause(actor.identity, 24)} actor has "
                f"{_count_word(actor.visible_hand_count or 0)} visible "
                f"{'hand' if actor.visible_hand_count == 1 else 'hands'}"
                for actor in contract.actors
            )
            hand_priority_clauses.insert(0, f"hand ownership: {ownership}")
        if contract.unused_hand_constraints:
            hand_priority_clauses.append(
                "unused hands: "
                + _clip_complete_clause(contract.unused_hand_constraints[0], 125)
            )

        if contract.actors:
            actor_layout = "; ".join(
                f"{_clip_complete_clause(actor.identity, 48)} at {actor.slot}"
                for actor in contract.actors
                if actor.slot
            )
            if actor_layout:
                clauses.append(f"actor slots: {actor_layout}")
    selected: list[str] = []
    for clause in (*hand_priority_clauses, *clauses):
        clause = _clean(clause)
        if not clause:
            continue
        candidate = "; ".join((*selected, clause))
        if len(candidate) > 390:
            continue
        selected.append(clause)
    return "; ".join(selected)


def _composition_person_terms(text: str) -> tuple[str, str]:
    if re.search(r"\bexactly\s+two\s+young\s+boys:\s*Biryu\s+and\s+Onjo\b", text, re.IGNORECASE):
        return "young boy", "young boys"
    if re.search(
        r"\bexactly\s+(?:three|five)\s+(?:living\s+)?named\s+people\b",
        text,
        re.IGNORECASE,
    ):
        return "person", "people"
    return "adult", "adults"


def _composition_contract(
    text: str,
    *,
    scene_kind: str,
    person_count: int | None,
    primary_subject: str = "",
    historical_montage_source: bool = False,
) -> tuple[str, str]:
    full_bleed = "Full-bleed 16:9; one viewpoint; scene reaches every edge"
    face_scene = _is_face_close_scene(text)
    chest_crop = bool(
        re.search(
            r"\b(?:head-and-shoulders|chest-up|tight\s+(?:facial|face)\s+close-up|"
            r"extreme\s+(?:facial|face)\s+close-up)\b",
            text,
            re.IGNORECASE,
        )
    )
    waist_crop = bool(re.search(r"\bwaist-up\b", text, re.IGNORECASE))
    explicit_no_animal_scene = bool(
        re.search(r"\bno\s+(?:horse|cow|animal)\b", text, re.IGNORECASE)
        or re.search(r"\b[\w-]*HUMAN[\w-]*-ONLY\s+SCENE\b", text, re.IGNORECASE)
    )
    mounted_bull_scene = bool(
        re.search(r"\b(?:bull|bulls)\b", text, re.IGNORECASE)
        and re.search(
            r"\b(?:rider|riders|mounted|astride|rides?|riding|seated\s+side-saddle)\b",
            text,
            re.IGNORECASE,
        )
    )
    submerged_mounted_bull_scene = bool(
        re.search(r"\bbull\b", text, re.IGNORECASE)
        and re.search(r"\bEuropa\b", text, re.IGNORECASE)
        and re.search(
            r"\b(?:swim|swims|swimming|submerged|underwater|open\s+sea|open\s+seawater|"
            r"hidden\s+below\s+the\s+sea|hidden\s+underwater)\b",
            text,
            re.IGNORECASE,
        )
        and (
            mounted_bull_scene
            or re.search(
                r"\b(?:clings?|clinging|wrapped\s+around|upper\s+back|horned\s+head)\b",
                text,
                re.IGNORECASE,
            )
        )
    )
    explicit_horse_scene = bool(
        re.search(
            r"\b(?:horse|horses|stallion|mare|cavalry|horseback)\b",
            text,
            re.IGNORECASE,
        )
    )
    horse_scene = bool(
        _MOUNTED_HORSE_RE.search(text)
        and (explicit_horse_scene or not mounted_bull_scene)
        and not explicit_no_animal_scene
    )
    battle_scene = bool(_BATTLE_RE.search(text))
    full_body_scene = bool(
        re.search(r"\b(?:full[- ]body|head\s+to\s+boots?|boots?\s+visible|feet\s+visible|walking|walks?)\b", text, re.IGNORECASE)
    )
    foreground_focus = _clip(primary_subject, 125)
    visible_hand_match = re.search(
        r"\bexactly\s+(zero|one|two|three|four|five|six|[0-6])\s+visible\s+(?:empty\s+)?hands?\b",
        text,
        re.IGNORECASE,
    )
    visible_hand_count = None
    if visible_hand_match:
        hand_token = visible_hand_match.group(1).lower()
        visible_hand_count = 0 if hand_token == "zero" else _COUNT_WORDS.get(
            hand_token, int(hand_token) if hand_token.isdigit() else None
        )

    if scene_kind == "pair" and re.search(
        r"\bBroad\s+flowing\s+river\s+water\s+(?:"
        r"fills\s+the\s+entire\s+(?:center\s+foreground|lower\s+two\s+thirds)|"
        r"reaches\s+the\s+bottom\s+center\s+edge)\b",
        text,
        re.IGNORECASE,
    ):
        return (
            "Composition: extreme wide view looking straight down one broad river channel; uninterrupted water "
            "runs from the bottom center edge through the middle of the frame to the horizon; one complete adult "
            "stands only on the far-left bank and one complete adult stands only on the far-right bank; dry ground "
            "never connects the two banks; no side-by-side foreground pair; full-bleed 16:9; one viewpoint.",
            "composition=japanese_myth_opposite_riverbanks",
        )

    if re.search(
        r"\bOBJECT-ONLY\s+EVIDENCE\s+VIEW\b[\s\S]{0,400}\bGupta\s+gold\s+coin\b",
        text,
        re.IGNORECASE,
    ):
        return (
            "Composition: strict straight-down 90-degree object-only view; exactly one small round Gupta gold coin "
            "lies at the exact center and measures about one tenth of the frame width; continuous matte-black velvet "
            "fills every remaining pixel to all four frame edges; zero person, human silhouette, body, limb, hand, "
            "animal, building, landscape, map, diagram, paper, label, writing, extra coin or second object; one "
            "viewpoint; full-bleed 16:9.",
            "composition=ch2_ep03_single_gupta_coin_on_black_velvet",
        )

    if (
        scene_kind == "single"
        and re.search(r"\bface-only\s+close-up\s+ending\s+at\s+the\s+jawline\b", text, re.IGNORECASE)
        and re.search(r"\bzero\s+visible\s+neck,\s*shoulders,\s*arms,\s*hands", text, re.IGNORECASE)
    ):
        return (
            "Composition: extreme face-only crop containing only hair and the complete face; lower frame edge ends "
            "exactly at the jawline; zero visible neck, shoulders, arms, hands, fingers, torso, waist, legs or feet; "
            "one viewpoint; full-bleed 16:9.",
            "composition=japanese_myth_jawline_face_only",
        )

    if (
        scene_kind == "pair"
        and re.search(r"\btwo-face-only\s+close-up\s+ending\s+at\s+both\s+jawlines\b", text, re.IGNORECASE)
        and re.search(r"\bzero\s+visible\s+necks,\s*shoulders,\s*arms,\s*hands", text, re.IGNORECASE)
    ):
        if re.search(
            r"\bAmaterasu's\s+strict\s+left-facing\s+profile\b[^.;]{0,260}"
            r"\bTsukuyomi's\s+strict\s+right-facing\s+profile\b",
            text,
            re.IGNORECASE,
        ):
            return (
                "Composition: exactly two outward-facing adult profiles only; Amaterasu's strict left-facing "
                "profile stays at far left; Tsukuyomi's strict right-facing profile stays at far right; zero visible "
                "necks, shoulders, arms, hands, fingers, torsos, waists, legs or feet; both noses point toward their "
                "nearest outer edges and the backs of their hair face a wide uninterrupted deep-blue empty center gap; "
                "neither face turns inward and no eye contact occurs; each lower frame edge ends exactly at its "
                "jawline before either neck begins; no third face; full-bleed 16:9; one viewpoint.",
                "composition=japanese_myth_outward_banishment_faces_only",
            )
        return (
            "Composition: exactly two complete adult faces and their hair crowns only; each lower frame edge ends "
            "exactly at its jawline before either neck begins; zero visible necks, shoulders, arms, hands, fingers, "
            "torsos, waists, legs or feet; positions, gaze directions and empty separation follow the visible action; "
            "no third face; full-bleed 16:9; one viewpoint.",
            "composition=japanese_myth_two_jawline_faces_only",
        )

    if (
        scene_kind == "group"
        and person_count == 4
        and re.search(r"\bpresent-day\s+comment-reading\s+face-only\s+group\b", text, re.IGNORECASE)
        and re.search(r"\bexactly\s+one\s+central\s+modern\s+tablet\b", text, re.IGNORECASE)
    ):
        return (
            "Composition: exactly four separated complete adult faces and their hair in one row above exactly one central "
            "modern tablet showing three blank comment rows; every lower face crop ends exactly at its jawline; zero visible "
            "necks, shoulders, arms, hands, fingers, torsos, waists, legs, or feet; no fifth face; one viewpoint; full-bleed 16:9.",
            "composition=present_day_four_comment_readers_hidden_limbs",
        )

    if (
        scene_kind == "group"
        and person_count == 4
        and re.search(r"\bfour-face-only\s+close-up\s+ending\s+at\s+all\s+four\s+jawlines\b", text, re.IGNORECASE)
        and re.search(r"\bzero\s+visible\s+necks,\s*shoulders,\s*arms,\s*hands", text, re.IGNORECASE)
    ):
        return (
            "Composition: exactly four separated complete adult faces and their hair only in one row; every lower crop "
            "ends exactly at its jawline before the neck begins; zero visible necks, shoulders, arms, hands, fingers, "
            "torsos, waists, legs, or feet; no fifth face; one viewpoint; full-bleed 16:9.",
            "composition=japanese_myth_four_fear_faces_only",
        )

    if (
        scene_kind == "group"
        and person_count == 4
        and re.search(r"\bexactly\s+four\s+simple\s+vertical\s+frame\s+looms\b", text, re.IGNORECASE)
        and re.search(r"\bevery\s+arm,\s*hand,\s*finger,\s*lower\s+torso,\s*leg,\s*and\s+foot\s+is\s+fully\s+hidden\b", text, re.IGNORECASE)
    ):
        return (
            "Composition: exactly four separated adult face-and-shoulder busts in one row behind exactly four "
            "simple vertical frame looms, one person per loom; all arms, hands, fingers, lower torsos, legs, and feet "
            "remain fully occluded by loom beams and plain woven cloth; no fifth face; one viewpoint; full-bleed 16:9.",
            "composition=japanese_myth_four_weavers_hidden_limbs",
        )

    if re.search(
        r"\b(?:featureless\s+primordial\s+darkness\s+without\s+land,\s*sky,\s*stars,\s*or\s+horizon|"
        r"landscape-only\s+continuous\s+charcoal-black\s+primordial\s+mist\s+filling\s+the\s+entire\s+canvas)\b",
        text,
        re.IGNORECASE,
    ):
        return (
            "Composition: full-canvas abstract primordial mist field with no central subject, no silhouette, "
            "no ground line, no horizon, and charcoal-black turbulence reaching every edge in full-bleed 16:9.",
            "composition=ch2_featureless_primordial_darkness",
        )
    if re.search(
        r"\b(?:deep\s+primordial\s+chasm\s+with\s+faint\s+mist\s+gathering\s+but\s+no\s+defined\s+landscape|"
        r"landscape-only\s+one\s+vast\s+bottomless\s+primordial\s+chasm)\b",
        text,
        re.IGNORECASE,
    ):
        return (
            "Composition: straight-down abstract full-bleed 16:9 view into one bottomless mist void with no person, "
            "no object, no ground plane, no horizon, and dark vapor reaching every edge.",
            "composition=ch2_primordial_chasm",
        )

    if historical_montage_source and _CONTINUOUS_HISTORICAL_PANORAMA_RE.search(text):
        return (
            "Composition: panorama; Onjo foreground; Biryu at his younger brother's packed-earth settlement midground; the "
            "same small collapsed torn unmarked undyed woven-cloth banner lies in narrow crumpled folds on sandy ground in the "
            "midground; distant Mahan campaign silhouettes background; "
            "one shared ground plane, one unbroken natural horizon, one continuous sky, one viewpoint; full-bleed 16:9.",
            "composition=continuous_historical_panorama",
        )
    if scene_kind == "landscape" and is_present_day_pungnap_archaeology(text):
        return (
            "Composition: one close low-angle full-bleed contemporary Pungnap archaeological location view; "
            "daylight-lit riverbank texture fills the entire bottom edge and both lower corners; one long low "
            "grass-covered rammed-earth city-wall embankment with a rounded crest stretches horizontally; the crop "
            "contains only earthen wall, riverbank soil, reeds, water, and blank natural sky; one viewpoint; full-bleed 16:9.",
            "composition=present_day_pungnap_full_bleed_landscape",
        )
    if scene_kind == "object" and is_guthe_origin_record_scene(text):
        has_relief = bool(re.search(r"\b(?:coastal|sea-route|night\s+sea-route)\s+relief\b", text, re.IGNORECASE))
        if has_relief:
            return (
                "Composition: straight-down 90-degree full-canvas archival view; exactly two closed face-down blank "
                "thread-bound manuscripts sit far left and center, each cover showing one uninterrupted field of plain "
                "aged tan fiber and one binding edge with zero ink marks, symbols, or title strokes; exactly one physically "
                "separate raised unlabeled clay coastline relief sits far right, its surface carrying only broad coast and "
                "wave contours with zero carved characters or compact glyph-like grooves; "
                "wide visible wood gaps separate all three objects; evenly lit warm-brown wood grain fills every edge "
                "and corner; one viewpoint; full-bleed 16:9.",
                "composition=guthe_origin_records_with_separate_relief",
            )
        return (
            "Composition: straight-down 90-degree full-canvas archival view; exactly two closed face-down blank "
            "thread-bound manuscripts sit far apart at left and right, each showing only plain aged tan fiber and one "
            "binding edge; one wide uninterrupted strip of warm-brown wood separates them; evenly lit wood grain fills "
            "every edge and corner; one viewpoint; full-bleed 16:9.",
            "composition=guthe_origin_records_only",
        )
    if primary_subject == (
        "exactly three adults: exiled Onjo, defeated Biryu, betrayed Mahan neighbor"
    ):
        return (
            "Composition: one continuous wide historical landscape; exiled Onjo, defeated Biryu, and one betrayed "
            "Mahan neighbor occupy three separated depth positions on one shared ground plane beneath one unbroken "
            "natural horizon and one continuous sky; no internal frames; one viewpoint; full-bleed 16:9.",
            "composition=continuous_ep01_three_fates",
        )
    if re.search(
        r"\bmounted\s+Malgal\s+raiders\b[^.;]{0,120}\beach\s+on\s+one\s+separate\s+horse\b",
        primary_subject,
        re.IGNORECASE,
    ):
        return (
            "Composition: wide mounted frontier action; every visible rider occupies one separate saddle on one separate horse; "
            "each rider has one head, one torso, two attached arms, and two attached legs resting along that rider's own saddle "
            "and horse rather than touching the ground; each horse has one head, "
            "one neck, one torso, exactly four attached legs, and one tail; open ground separates every rider-horse unit; "
            "full-bleed 16:9.",
            "composition=ep01_mounted_malgal_group",
        )
    if primary_subject.startswith(
        "living Onjo and secondary living Baekje attackers outside Ugokseong; exactly one fully shrouded deceased Jugun form inside"
    ):
        return (
            "Composition: one continuous wide Ugok assault view; living Onjo and each living Baekje attacker remain outside "
            "the stronghold as separate coherent bodies, each with one head, one torso, two attached arms and two grounded legs; "
            "inside, exactly one continuous fully closed Jugun shroud lies apart and receives no visible head, hand, finger, arm, "
            "leg or foot anatomy; one viewpoint; full-bleed 16:9.",
            "composition=ugok_assault_shrouded_jugun_exempt",
        )
    if primary_subject.startswith(
        "non-graphic covered Ugok aftermath: exactly one deceased Jugun identity under one continuous full-body shroud"
    ):
        return (
            "Composition: exactly one body-length fully closed Jugun shroud lies on exactly one bier as one deceased identity; "
            "one waist-level covering seam remains only a surface cue and never separates the shroud into two bodies; a separate "
            "uncounted fully covered wife-and-children group remains behind it; every human form stays concealed; one restrained "
            "viewpoint; full-bleed 16:9.",
            "composition=ugok_single_jugun_identity_uncounted_family",
        )
    if primary_subject == (
        "exactly one deceased man Biryu fully covered by a plain unmarked shroud"
    ):
        return (
            "Composition: exactly one fully wrapped shrouded form lies horizontally on one low plain timber bier; "
            "the unbroken shroud covers the entire form from head to feet and conceals face, hands, fingers, arms, "
            "and legs; one restrained viewpoint; full-bleed 16:9.",
            "composition=biryu_fully_shrouded_aftermath",
        )
    if (
        primary_subject.startswith("animal-only: exactly one")
        and "blue dragon" in primary_subject.lower()
    ):
        return (
            "Composition: exactly one complete blue dragon form rises above one well; one coherent silhouette, "
            "one head, one continuous serpentine body, exactly four attached legs, and one tail; one viewpoint; "
            "an intact early Baekje packed-earth settlement, plain timber palisade, and modest rough-thatch roofs "
            "surround the well; uninterrupted earth and timber texture fills every corner including the lower right; "
            "full-bleed 16:9.",
            "composition=single_blue_dragon",
        )
    if _CONTINUOUS_HISTORICAL_TRANSITION_RE.search(text):
        return (
            "Composition: one continuous wide historical landscape on one shared ground plane; Onjo's disguised hunting "
            "force turns toward the Mahan center in the foreground while the same uninterrupted terrain recedes into the "
            "ancient northern origin landscape beneath one unbroken natural horizon and one continuous sky; one viewpoint; "
            "full-bleed 16:9.",
            "composition=continuous_historical_transition_panorama",
        )

    if person_count == 1 and re.search(r"Emperor\s+Gaozong\s+directing\s+the\s+Pyongyang\s+campaign", text, re.IGNORECASE):
        return (
            "Composition: black futou covers Gaozong's hair; he points at one solid unmarked earth relief with raised walls and "
            "recessed roads; a low table and blank windowless plaster fill the frame; full-bleed 16:9.",
            "composition=gaozong_points_at_pyongyang_relief",
        )
