def _clip(value: str, max_chars: int) -> str:
    text = _clean(value)
    if len(text) <= max_chars:
        return text
    shortened = text[: max_chars + 1].rsplit(" ", 1)[0].rstrip(" ,;:.")
    return _trim_dangling_tail(shortened or text[:max_chars].rstrip(" ,;:."))


def _trim_dangling_tail(value: str) -> str:
    text = value.rstrip(" ,;:.")
    dangling = re.compile(
        r"\s+\b(?:a|an|the|and|or|with|in|on|at|to|from|of|for|over|under|into|through|"
        r"toward|towards|beside|between|behind|before|after|as|while|beyond)\b$",
        re.IGNORECASE,
    )
    while dangling.search(text):
        text = dangling.sub("", text).rstrip(" ,;:.")
    return text


def _final_positive_cleanup(value: str) -> str:
    cinematic_live_action = _uses_cinematic_live_action_style(value)
    parts: list[str] = []
    for sentence in re.split(r"(?<=[.!?])\s+", value):
        cleaned = _sanitize_positive_fragment(sentence)
        if not cleaned:
            continue
        if _NEGATIVE_LANGUAGE_RE.match(cleaned):
            continue
        if not cinematic_live_action:
            cleaned = _rewrite_risky_visible_terms(cleaned)
        if not cinematic_live_action and _POSITIVE_RISK_WORD_RE.search(cleaned):
            cleaned = _POSITIVE_RISK_WORD_RE.sub("plain surface detail", cleaned)
        parts.append(cleaned.rstrip("."))
    return ". ".join(parts).strip(" .") + "."
